/* @lc app=leetcode id=3169 lang=kotlin */ class Solution { fun countDays(days: Int, meetings: Array<IntArray>): Int = meetings.sortedBy { it[0] }.let { sorted -> sorted.drop(1).fold(intArrayOf(sorted[0][0], sorted[0][1], 0)) { acc, m -> if (m[0] <= acc[1]) acc.also { it[1] = maxOf(it[1], m[1]) } else acc.also { it[2] += acc[1] - acc[0] + 1 }.also { it[0] = m[0] }.also { it[1] = m[1] } }.let { acc -> days - (acc[2] + (acc[1] - acc[0] + 1)) } } }